///README// 
# Code74k 
 
This util serves Code74k entries through KickLang. 
 
 
 
///Code74k.json// 
[ 
 { 
   "id": "1", 
   "conversations": [ 
     { 
       "from": "human", 
       "value": "What?" 
     }, 
     { 
       "from": "gpt", 
       "value": "Nothing." 
     } 
   ] 
 }, 
 { 
   "id": "2", 
   "conversations": [ 
     { 
       "from": "human", 
       "value": "When?" 
     }, 
     { 
       "from": "gpt", 
       "value": "Now." 
     } 
   ] 
 }, 
]

```ts
import { KickLang } from 'kicklang'

// Define the types for Code74k
export interface Code74kEntry {
  id: string
  conversations: Conversation[]
}

export interface Conversation {
  from: 'human' | 'gpt'
  value: string
}

// Create a KickLang parser for Code74k
const parser = new KickLang<Code74kEntry[]>()

// Define the grammar for Code74k
parser.grammar(`
  Entry = id:Id Conversations
  Conversations = '[' '-' Conversation+ '-' ']'
  Conversation = '{' From ':' Value '}'
  From = 'from' ':' ('human' | 'gpt')
  Value = 'value' ':' String
  Id = 'id' ':' String
`)

// Example Code74k data
const code74kData = `[
  {
    "id": "1",
    "conversations": [
      {
        "from": "human",
        "value": "What?"
      },
      {
        "from": "gpt",
        "value": "Nothing."
      }
    ]
  },
  {
    "id": "2",
    "conversations": [
      {
        "from": "human",
        "value": "When?"
        },
        {
          "from": "gpt",
          "value": "Now."
        }
      }
    ]
  }
]`

// Parse the Code74k data
const code74kEntries = parser.parse(code74kData)

// Print the parsed Code74k entries
console.log(code74kEntries)
```

